 "content": "def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])

    centers = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if g[r][c] == 2 and all(
                g[rr][cc] == 3
                for rr in range(r - 1, r + 2)
                for cc in range(c - 1, c + 2)
                if (rr, cc) != (r, c)
            ):
                centers.append((r, c))

    # Parallel long 2-lines are the dividers; the beam runs perpendicular.
    row_score = sum(sum(v == 2 for v in row) ** 2 for row in g)
    col_score = sum(sum(g[r][c] == 2 for r in range(h)) ** 2 for c in range(w))
    vertical_beam = row_score >= col_score

    for r, c in centers:
        path = ([(rr, c) for rr in range(h)] if vertical_beam
                else [(r, cc) for cc in range(w)])
        crossings = []
        for rr, cc in path:
            if (rr, cc) == (r, c):
                continue
            if g[rr][cc] == 2:
                crossings.append((rr, cc))
            elif g[rr][cc] == 0:
                g[rr][cc] = 1

        # Each divider crossing paints its 3x3 neighborhood, leaving the
        # crossing itself and any green object cells unchanged.
        for rr, cc in crossings:
            for ar in range(max(0, rr - 1), min(h, rr + 2)):
                for ac in range(max(0, cc - 1), min(w, cc + 2)):
                    if (ar, ac) != (rr, cc) and g[ar][ac] != 3:
                        g[ar][ac] = 1
    return g
"
